}

.fr-name {
  flex: 1 1 auto;
  min-width: 0;
}

.fr-title {
  font-weight: 600;
}

.fr-note {
  color: var(--text-3);
  font-size: var(--fs-sm);
}

.fr-px {
  margin-left: 8px;
  color: var(--text-2);
  font-size: var(--fs-sm);
