}

.hero.hero-hub .hero-title {
  margin-top: 0;
}

.hero.hero-hub .hero-sub {
  margin-top: 2px;
}

.hero.hero-hub .chip {
  margin-top: 8px;
}

.soon-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 16px 14px;
  margin-bottom: 10px;
  border-radius: var(--r-card);
