}

/* ---------- AI Generative Studio ---------- */

.ai-prompt {
  display: block;
  width: 100%;
  min-height: 64px;
  margin: 0 0 10px 0;
  padding: 8px 10px;
  font-size: 13px;
  line-height: 1.4;
  resize: vertical;
  box-sizing: border-box;
}

.chip-pick-row {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 6px;
}

.chip-pick {
  padding: 5px 10px;
  border-radius: 12px;
  background-color: var(--glass);
  border: 1px solid var(--stroke);
  color: var(--text-2);
  font-size: 11px;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.chip-pick:hover {
  border-color: var(--accent);
  color: var(--text);
}

.ai-progress-track {
  position: relative;
  height: 10px;
  border-radius: 999px;
  background-color: var(--stroke);
  overflow: hidden;
  margin: 8px 0 4px 0;
}

.ai-progress-fill {
  position: absolute;
  inset: 0;
  width: 0%;
  border-radius: 999px;
  background-image: linear-gradient(90deg, #ffb347, #ff7a18, #ffd27a, #ff7a18, #ffb347);
  background-size: 200% 100%;
  animation: ai-shimmer 1.6s linear infinite;
  box-shadow: 0 0 10px rgba(255, 138, 0, 0.55);
  transition: width 220ms ease;
}

@keyframes ai-shimmer {
  0% {
    background-position: 0% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.ai-progress-pct {
  float: right;
  font-size: 11px;
  color: var(--text-3);
  margin-top: -4px;
}

.ai-progress-step {
  font-size: var(--fs-sm);
  color: var(--text-2);
  margin: 2px 0 10px 0;
  clear: both;
}
